#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Node {
    int value;
    struct Node *next;
};

struct Node *head = NULL;

void insert(int x) {
    struct Node *n = malloc(sizeof(struct Node));
    n->value = x;
    n->next = head;
    head = n;
}

void delete_value(int x) {
    struct Node *cur = head, *prev = NULL;
    while (cur) {
        if (cur->value == x) {
            if (prev) prev->next = cur->next;
            else head = cur->next;
            free(cur);
            return;
        }
        prev = cur;
        cur = cur->next;
    }
}

int find(int x) {
    for (struct Node *cur = head; cur; cur = cur->next)
        if (cur->value == x) return 1;
    return 0;
}

void print_list(void) {
    int first = 1;
    for (struct Node *cur = head; cur; cur = cur->next) {
        if (!first) printf(" ");
        printf("%d", cur->value);
        first = 0;
    }
    printf("\n");
}

int main(void) {
    char cmd[64];
    int x;
    while (scanf("%63s", cmd) == 1) {
        if (strcmp(cmd, "insert") == 0) {
            if (scanf("%d", &x) == 1) insert(x);
        } else if (strcmp(cmd, "delete") == 0) {
            if (scanf("%d", &x) == 1) delete_value(x);
        } else if (strcmp(cmd, "find") == 0) {
            if (scanf("%d", &x) == 1) printf("%d\n", find(x));
        } else if (strcmp(cmd, "print") == 0) {
            print_list();
        }
    }
    return 0;
}
